def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    rich_aggressive = 0
    weak_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 2:
                weak_opponents += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 85 and opp.get('budget', 0) >= 150:
                    rich_aggressive += 1

    if not alive_opponents:
        return float(min(budget, 15.0))

    slots = max(1, int(supply // WATER_REQ))
    opp_count = len(alive_opponents)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water >= 2:
        urgency += 4
    elif no_water >= 1:
        urgency += 2
    if slots <= 1:
        urgency += 2
    if day >= 8:
        urgency += 1

    if urgency >= 7:
        target = max(92.0, highest_prev + 3.0)
    elif urgency >= 4:
        target = max(72.0, avg_prev + 2.0, highest_prev * 0.9)
    else:
        if slots >= 2:
            target = 24.0
            if rich_aggressive >= 2:
                target = 18.0
            if weak_opponents >= 2:
                target = 28.0
        else:
            target = 38.0
            if highest_prev > 95:
                target = 26.0
            elif highest_prev > 70:
                target = 34.0

    if budget < DAILY_SALARY * 2:
        target = min(target, budget * 0.6)
    elif budget < DAILY_SALARY * 4:
        target = min(target, budget * 0.45)

    if hp >= 8 and no_water == 0 and rich_aggressive >= 2 and slots >= 1 and day <= 7:
        target = min(target, 20.0)

    if hp <= 2 or no_water >= 2:
        target = max(target, 88.0)

    bid = max(0.0, min(float(budget), float(target)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return 10

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if not yesterday_bids:
        avg_prev = 80
    else:
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)

    if supply <= 16:
        bid = min(my_status['budget'], avg_prev + 10)
    elif supply >= 22:
        bid = min(my_status['budget'], max(30, avg_prev - 20))
    else:
        bid = min(my_status['budget'], avg_prev)

    if my_status['hp'] < 4:
        bid = min(my_status['budget'], bid * 1.5)

    return max(0.0, float(bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    EPISODE_DAYS = 10 

    CRITICAL_HP = 2
    LOW_HP = 4

    remaining_days = EPISODE_DAYS - day_context['day']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)
    total_players_competing = num_alive_opponents + 1 

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    strong_opponent_bids_yesterday = []
    for opp_id, opp_data in opponents_status.items():
        if opp_data['alive']:
            prev_trace = opp_data.get('previous_trace', {})
            if prev_trace and prev_trace.get('bid') is not None:
                strong_opponent_bids_yesterday.append(prev_trace['bid'])

    max_opp_bid_yesterday = 0
    if strong_opponent_bids_yesterday:
        max_opp_bid_yesterday = max(strong_opponent_bids_yesterday)

    bid = DAILY_SALARY # Default base bid
    num_slots = int(day_context['supply'] // WATER_REQ)

    if my_status['hp'] <= CRITICAL_HP:
        bid = max(DAILY_SALARY * 1.5, max_opp_bid_yesterday + 5)
    elif my_status['hp'] <= LOW_HP:
        bid = max(DAILY_SALARY * 1.2, max_opp_bid_yesterday + 2)
    else: # Healthy HP (my_status['hp'] > LOW_HP)
        if total_players_competing > num_slots:
            # Water is scarce, not enough for everyone. Competition is high.
            bid = max(DAILY_SALARY * 1.1, max_opp_bid_yesterday + 1)
            if total_players_competing - num_slots >= 2: # At least two players will miss out
                 bid = max(bid, DAILY_SALARY * 1.25)

        else:
            # Water is sufficient for everyone to get their requirement (or more than enough slots)
            bid = max(DAILY_SALARY * 0.9, max_opp_bid_yesterday * 0.9)
            if max_opp_bid_yesterday == 0: 
                bid = DAILY_SALARY * 0.7 
            if bid < DAILY_SALARY * 0.5: 
                bid = DAILY_SALARY * 0.5

    # End-game strategy (last 2 days)
    if remaining_days <= 2:
        if my_status['hp'] <= LOW_HP: 
            bid = max(bid, my_status['budget'] * 0.95) 
        elif my_status['budget'] >= DAILY_SALARY * 3 and my_status['hp'] >= WATER_REQ: 
            bid = max(bid, max_opp_bid_yesterday + DAILY_SALARY * 0.4)
            bid = min(bid, my_status['budget'] * 0.7) 

    final_bid = max(1.0, min(my_status['budget'], bid))

    return final_bid
